body:
I think it's doable to reimplement `unproject_position()` in GDScript, and call from there the fixed version of `_get_camera_projection()` that has to be reimplemented in GDScript too :

```c++
Point2 Camera3D::unproject_position(const Vector3 &p_pos) const {
	ERR_FAIL_COND_V_MSG(!is_inside_tree(), Vector2(), "Camera is not inside scene.");

	Size2 viewport_size = get_viewport()->get_visible_rect().size;

	Projection cm = _get_camera_projection(_near); // This must use the fixed version

	Plane p(get_camera_transform().xform_inv(p_pos), 1.0);

	p = cm.xform4(p);

	// Prevent divide by zero.
	// TODO: Investigate, this was causing NaNs.
	ERR_FAIL_COND_V(p.d == 0, Point2());

	p.normal /= p.d;

	Point2 res;
	res.x = (p.normal.x * 0.5 + 0.5) * viewport_size.x;
	res.y = (-p.normal.y * 0.5 + 0.5) * viewport_size.y;

	return res;
}

```

```c++
Projection Camera3D::_get_camera_projection(real_t p_near) const {
	Size2 viewport_size = get_viewport()->get_camera_rect_size();
	Projection cm;

	switch (mode) {
		case PROJECTION_PERSPECTIVE: {
			cm.set_perspective(fov, viewport_size.aspect(), p_near, _far, keep_aspect == KEEP_WIDTH);
		} break;
		case PROJECTION_ORTHOGONAL: {
			cm.set_orthogonal(size, viewport_size.aspect(), p_near, _far, keep_aspect == KEEP_WIDTH);
		} break;
		case PROJECTION_FRUSTUM: {
			cm.set_frustum(size, viewport_size.aspect(), frustum_offset, p_near, _far, keep_aspect == KEEP_WIDTH);
		} break;
	}

	return cm;
}
```

So, this is Camera3D.UnprojectPosition() method as workaround:
```
	private static Vector2 UnprojectPosition(Camera3D camera, Vector3 p_pos)
	{
		Vector2 viewport_size = camera.GetViewport().GetVisibleRect().Size;

		Projection cm = GetCameraProjection(camera);

		Plane p = new Plane(XformInv(GetCameraTransform(camera), p_pos), 1.0f);

		p = Xform4(cm, p);
		p.Normal /= p.D;

		return new Vector2(
			(p.Normal.X * 0.5f + 0.5f) * viewport_size.X,
			(-p.Normal.Y * 0.5f + 0.5f) * viewport_size.Y
		);
	}
```
Fixed C++ Projection Camera3D::get_camera_projection():
```
	private static Projection GetCameraProjection(Camera3D camera)
	{
		Vector2 viewport_size = camera.GetViewport().GetVisibleRect().Size;
		Projection cm = new Projection();

		switch (camera.Projection)
		{
			case Camera3D.ProjectionType.Perspective:
				cm = Projection.CreatePerspective(camera.Fov, viewport_size.Aspect(), camera.Near, camera.Far, camera.KeepAspect == Camera3D.KeepAspectEnum.Width);
				break;

			case Camera3D.ProjectionType.Orthogonal:
				cm = Projection.CreateOrthogonalAspect(camera.Size, viewport_size.Aspect(), camera.Near, camera.Far, camera.KeepAspect == Camera3D.KeepAspectEnum.Width);
				break;

			case Camera3D.ProjectionType.Frustum:
				cm = Projection.CreateFrustumAspect(camera.Size, viewport_size.Aspect(), camera.FrustumOffset, camera.Near, camera.Far, camera.KeepAspect == Camera3D.KeepAspectEnum.Width);
				break;
		}

		return cm;
	}
```
Internal C++ Transform3D Camera3D::get_camera_transform():
```
	private static Transform3D GetCameraTransform(Camera3D camera)
	{
		Transform3D tr = camera.GlobalTransform.Orthonormalized();
		tr.Origin += tr.Basis.Column1 * camera.VOffset;
		tr.Origin += tr.Basis.Column0 * camera.HOffset;

		return tr;
	}
```
Internal C++ Vector3 Transform3D::xform_inv(const Vector3 &p_vector):
```
	private static Vector3 XformInv(Transform3D transform, Vector3 p_vector)
	{
		Vector3 v = p_vector - transform.Origin;

		Basis basis = transform.Basis;

		return new Vector3(
			(basis.Row0[0] * v.X) + (basis.Row1[0] * v.Y) + (basis.Row2[0] * v.Z),
			(basis.Row0[1] * v.X) + (basis.Row1[1] * v.Y) + (basis.Row2[1] * v.Z),
			(basis.Row0[2] * v.X) + (basis.Row1[2] * v.Y) + (basis.Row2[2] * v.Z)
		);
	}
```
And internal C++ Plane Projection::xform4(const Plane &p_vec4):
```
	private static Plane Xform4(Projection projection, Plane p_vec4)
	{
		Vector3 normal = new Vector3(
			projection[0][0] * p_vec4.Normal.X + projection[1][0] * p_vec4.Normal.Y + projection[2][0] * p_vec4.Normal.Z + projection[3][0] * p_vec4.D,
			projection[0][1] * p_vec4.Normal.X + projection[1][1] * p_vec4.Normal.Y + projection[2][1] * p_vec4.Normal.Z + projection[3][1] * p_vec4.D,
			projection[0][2] * p_vec4.Normal.X + projection[1][2] * p_vec4.Normal.Y + projection[2][2] * p_vec4.Normal.Z + projection[3][2] * p_vec4.D
		);

		float d = projection[0][3] * p_vec4.Normal.X + projection[1][3] * p_vec4.Normal.Y + projection[2][3] * p_vec4.Normal.Z + projection[3][3] * p_vec4.D;

		return new Plane(normal, d);
	}
```
Edit: Oh and I'm running 4.3.1, so that godot source I used as reference.
Edit: Added GetCameraProjection() reimplementation with fix.

> I still need project_ray_origin and project_ray_normal to be ported and I'm not sure where to start with those.

As far as I remember `project_ray_origin` is not affected by this PR because it always returns the camera origin in Frustum and Perspective modes. You should be able to use the vanilla version here.

For `project_ray_normal` you need to rewrite the following in GDScript : 

```c++
Vector3 Camera3D::project_ray_normal(const Point2 &p_pos) const {
	Vector3 ray = project_local_ray_normal(p_pos);
	return get_camera_transform().basis.xform(ray).normalized();
}

Vector3 Camera3D::project_local_ray_normal(const Point2 &p_pos) const {
	ERR_FAIL_COND_V_MSG(!is_inside_tree(), Vector3(), "Camera is not inside scene.");

	Size2 viewport_size = get_viewport()->get_camera_rect_size();
	Vector2 cpos = get_viewport()->get_camera_coords(p_pos);
	Vector3 ray;

	if (mode == PROJECTION_ORTHOGONAL) {
		ray = Vector3(0, 0, -1);
	} else {
		Projection cm = _get_camera_projection(_near); // This must be the fixed version 
		Vector2 top_right = cm.get_viewport_half_extents();
		Vector2 offset = Vector2();
		if (mode == PROJECTION_FRUSTUM) {
			offset = frustum_offset;
		}
		ray = Vector3(((cpos.x / viewport_size.width) * 2.0 - 1.0) * top_right.x + offset.x, ((1.0 - (cpos.y / viewport_size.height)) * 2.0 - 1.0) * top_right.y + offset.y, -_near).normalized();
	}

	return ray;
}
```

